// Generates src/design-system/tokens/token-names.ts from the token CSS files so that
// TypeScript knows every custom property name. Run `npm run tokens:gen` after a token update;
// `npm test` fails (tokens.test.ts) when the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'src', 'design-system', 'tokens');

export function collectTokenNames() {
  const names = new Set();
  for (const file of ['aegean.css', 'aegean-extensions.css']) {
    const css = readFileSync(join(dir, file), 'utf8');
    for (const match of css.matchAll(/^\s*--([a-z0-9_-]+)\s*:/gim)) {
      names.add(match[1]);
    }
  }
  return [...names].sort();
}

export function renderTokenNames(names) {
  const lines = names.map((n) => `  '${n}',`).join('\n');
  return `// Generated by scripts/gen-token-names.mjs from aegean.css and aegean-extensions.css. Do not edit.\nexport const tokenNames = [\n${lines}\n] as const;\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(dir, 'token-names.ts'), renderTokenNames(collectTokenNames()));
  console.log('token-names.ts written');
}
